"""Автономный просмотр всех пар и двух карт без сети и модельных вызовов."""
import base64
import gzip
import json


def render_comparison(result):
    payload = base64.b64encode(gzip.compress(json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(), mtime=0)).decode()
    return TEMPLATE.replace("__PAYLOAD__", payload)


TEMPLATE = r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>Сравнение статей — карта знаний</title><style>
body{font:14px system-ui;margin:0;background:#f1f5f9;color:#172033}header,main{padding:18px}header{background:white;border-bottom:1px solid #cbd5e1}h1{font-size:22px}button,select{padding:8px;border:1px solid #94a3b8;border-radius:6px;background:white;color:#172033;max-width:100%}button{cursor:pointer;background:#2563eb;color:white}button:disabled{opacity:.5}label{display:inline-block;margin:5px}.matches{max-height:350px;overflow:auto;border:1px solid #e2e8f0}th{position:sticky;top:0;background:white;z-index:1}td:first-child{width:75%}table{width:100%;border-collapse:collapse;background:white}td,th{padding:10px;text-align:left;border-bottom:1px solid #e2e8f0}tr.sel{background:#dbeafe}tbody tr{cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pane{background:white;border:1px solid #cbd5e1;min-width:0}svg{width:100%;height:420px;touch-action:none;background:#f8fafc}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto;padding:12px;font:12px/1.5 system-ui}details{margin:10px 0}.note{color:#475569}.error{color:#991b1b}@media(max-width:900px){.grid{grid-template-columns:1fr}}
</style><header><h1 id="title">Сравнение статей</h1><p id="status">Загрузка автономных данных…</p><label>Режим <select id="mode"><option value="hybrid">Совместный RRF 60</option><option value="text">BM25</option><option value="semantic">Семантический</option></select></label><label>Знание цели <select id="left"></select></label><label>Источник <select id="source"><option value="">Все</option></select></label><label>Отношение <select id="relation"><option value="">Все</option><option>equivalent</option><option>partial</option><option>template</option><option>topical</option><option>contradiction</option><option>insufficient</option></select></label><label>Подписи <select id="locale"><option value="en">English</option><option value="ru">Русский</option></select></label><button id="download">JSON</button></header><main>
<div class="matches"><table><thead><tr><th>Соответствие</th><th>Оценки / отношения / покрытие</th></tr></thead><tbody id="rows"></tbody></table></div><p><button id="prev">Назад</button> <span id="page"></span> <button id="next">Далее</button></p>
<div class="grid"><div class="pane"><h3>Целевая карта</h3><button id="fitLeft">Обзор</button><svg id="mapLeft"></svg></div><div class="pane"><h3>Карта источника</h3><button id="fitRight">Обзор</button><svg id="mapRight"></svg></div></div>
<p class="note">Колесо — масштаб, перетаскивание — перемещение, выбор блока/стрелки — исходный фрагмент и семантика. Шаблон и форма цепочки не означают эквивалентность фактов.</p><details><summary>Сопоставленные утверждения и расхождения</summary><pre id="differences"></pre></details><div class="grid"><div><h3>Источник цели</h3><div id="sourceLeft"></div></div><div><h3>Источник соответствия</h3><div id="sourceRight"></div></div></div><details><summary>Контроль цитат и версии</summary><pre id="controls"></pre></details></main>
<script type="module">
const $=id=>document.getElementById(id), ns='http://www.w3.org/2000/svg'; let D,offset=0,chosen,rows=[];
const bytes=Uint8Array.from(atob('__PAYLOAD__'),c=>c.charCodeAt(0));
try{D=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
$('status').textContent=D.analysis.pair_count+' пар; модели/эмбеддинги: 0. Авторство Codex, требуется экспертная проверка. '+D.comparison_id;
$('controls').textContent=JSON.stringify({binding:D.binding,evaluation:D.evaluation},null,2);
for(const k of D.maps[0].graph.knowledge){let o=new Option(k.knowledge_id+' · '+k.display_text,k.knowledge_id);$('left').add(o)}
for(const m of D.maps.slice(1))$('source').add(new Option(m.article_id,m.article_id));
function text(m,id){return ($('locale').value==='ru'&&m.translations?.ru?.knowledge_labels?.[id])||m.graph.knowledge.find(k=>k.knowledge_id===id)?.display_text||id}
function fragments(m,ids,where,extra){let el=$(where);el.replaceChildren();for(let u of m.source.units.filter(u=>ids.includes(u.id))){let de=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('pre');s.textContent=u.id+' · '+u.start+'–'+u.end+' · Unicode code points';p.textContent=u.text;de.append(s,p);for(let a of m.source_attachments||[])if(a.unit_id===u.id){let pre=document.createElement('pre');pre.textContent=a.text;de.append(pre)}el.append(de)}if(extra){let p=document.createElement('pre');p.textContent=JSON.stringify(extra,null,2);el.append(p)}}
function svgElement(tag,attrs={},content){let el=document.createElementNS(ns,tag);for(let [k,v]of Object.entries(attrs))el.setAttribute(k,v);if(content!==undefined)el.textContent=content;return el}
function draw(m,kid,svgId,sourceId,fitId){let svg=$(svgId);svg.replaceChildren();let defs=svgElement('defs'),marker=svgElement('marker',{id:'arrow-'+svgId,viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:5,markerHeight:5,orient:'auto'});marker.append(svgElement('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:'#94a3b8'}));defs.append(marker);svg.append(defs);let pos={},counts={};for(let n of m.graph.nodes){let row=counts[n.rank]||0;counts[n.rank]=row+1;pos[n.id]={x:40+n.rank*270,y:40+row*120,n}}
let maxX=Math.max(600,...Object.values(pos).map(p=>p.x+250)),maxY=Math.max(420,...Object.values(pos).map(p=>p.y+100)),box=[0,0,maxX,maxY];let apply=()=>svg.setAttribute('viewBox',box.join(' '));apply();$(fitId).onclick=()=>{box=[0,0,maxX,maxY];apply()};
for(let e of m.graph.edges){let a=pos[e.source],b=pos[e.target];let p=svgElement('path',{d:'M'+(a.x+230)+' '+(a.y+45)+' L'+b.x+' '+(b.y+45),stroke:'#94a3b8','stroke-width':3,fill:'none','marker-end':'url(#arrow-'+svgId+')'});p.onclick=()=>{let t=m.graph.transitions.filter(t=>t.target===e.target&&t.sources.includes(e.source));fragments(m,[...new Set(t.flatMap(t=>t.unit_ids))],sourceId,t)};svg.append(p)}
for(let p of Object.values(pos)){let selected=p.n.knowledge_id===kid,g=svgElement('g');g.append(svgElement('rect',{x:p.x,y:p.y,width:230,height:90,rx:8,fill:selected?'#dbeafe':'white',stroke:selected?'#2563eb':p.n.block_type==='action'?'#ea580c':'#64748b','stroke-width':selected?4:1}));let words=text(m,p.n.knowledge_id).match(/.{1,30}(?:\s|$)|.{1,30}/g)||[];g.append(svgElement('title',{},text(m,p.n.knowledge_id)));g.append(svgElement('text',{x:p.x+10,y:p.y+17,'font-size':11,fill:'#475569'},p.n.knowledge_id+' · '+p.n.block_type));words.slice(0,3).forEach((w,i)=>g.append(svgElement('text',{x:p.x+10,y:p.y+35+i*17,'font-size':12},w.trim())));g.onclick=()=>{if(svgId==='mapLeft'){$('left').value=p.n.knowledge_id;offset=0;render()}else{let pair=D.pairs.find(q=>q.left_knowledge_id===$('left').value&&q.right_article_id===m.article_id&&q.right_knowledge_id===p.n.knowledge_id);if(pair)select(pair)}};svg.append(g);if(selected){box=[p.x-35,p.y-60,550,360]}}
apply();svg.onwheel=e=>{e.preventDefault();let f=e.deltaY>0?1.2:.8333;box=[box[0]+box[2]*(1-f)/2,box[1]+box[3]*(1-f)/2,box[2]*f,box[3]*f];apply()};let down;svg.onpointerdown=e=>{down={x:e.clientX,y:e.clientY,box:[...box]}};svg.onpointermove=e=>{if(!down)return;box[0]=down.box[0]-(e.clientX-down.x)*down.box[2]/svg.clientWidth;box[1]=down.box[1]-(e.clientY-down.y)*down.box[3]/svg.clientHeight;apply()};svg.onpointerup=svg.onpointerleave=()=>down=null}
function select(p){chosen=p;document.querySelectorAll('#rows tr').forEach(tr=>tr.classList.toggle('sel',tr.dataset.id===p.pair_id));let lm=D.maps[0],rm=D.maps.find(m=>m.article_id===p.right_article_id),lk=lm.graph.knowledge.find(k=>k.knowledge_id===p.left_knowledge_id),rk=rm.graph.knowledge.find(k=>k.knowledge_id===p.right_knowledge_id);$('differences').textContent=JSON.stringify({statement_matches:p.statement_matches,coverage:[p.coverage_left,p.coverage_right],template:p.template_score,chain_shape:p.dag_shape_score},null,2);fragments(lm,lk.provenance.unit_ids,'sourceLeft',lk.semantic_frame);fragments(rm,rk.provenance.unit_ids,'sourceRight',rk.semantic_frame);draw(lm,lk.knowledge_id,'mapLeft','sourceLeft','fitLeft');draw(rm,rk.knowledge_id,'mapRight','sourceRight','fitRight')}
function render(){for(let option of $('left').options){option.textContent=option.value+' · '+text(D.maps[0],option.value)}let mode=$('mode').value;rows=D.pairs.filter(p=>p.left_knowledge_id===$('left').value&&(!$('source').value||p.right_article_id===$('source').value)&&(!$('relation').value||p.relations.includes($('relation').value))).sort((a,b)=>b[mode+'_score']-a[mode+'_score']||a.right_article_id.localeCompare(b.right_article_id)||a.right_knowledge_id.localeCompare(b.right_knowledge_id));$('rows').replaceChildren();for(let p of rows.slice(offset,offset+10)){let m=D.maps.find(m=>m.article_id===p.right_article_id),tr=document.createElement('tr'),a=document.createElement('td'),b=document.createElement('td');tr.dataset.id=p.pair_id;a.textContent=m.article_id.split('-')[2].toUpperCase()+' · '+p.right_knowledge_id+' · '+text(m,p.right_knowledge_id);b.textContent=p.relations.join(', ')+' | BM25 '+p.text_score.toFixed(2)+' | S '+p.semantic_score.toFixed(3)+' | RRF '+p.hybrid_score.toFixed(4)+' | '+(p.coverage_left*100).toFixed(0)+'% / '+(p.coverage_right*100).toFixed(0)+'%';tr.append(a,b);tr.onclick=()=>select(p);$('rows').append(tr)}$('page').textContent=(rows.length?offset+1:0)+'–'+Math.min(offset+10,rows.length)+' / '+rows.length;$('prev').disabled=!offset;$('next').disabled=offset+10>=rows.length;if(rows[offset])select(rows[offset]);else{$('mapLeft').replaceChildren();$('mapRight').replaceChildren();$('sourceLeft').replaceChildren();$('sourceRight').replaceChildren();$('differences').textContent='Нет результатов'}}
for(let id of ['mode','left','source','relation'])$(id).onchange=()=>{offset=0;render()};$('locale').onchange=render;$('prev').onclick=()=>{offset-=10;render()};$('next').onclick=()=>{offset+=10;render()};$('download').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='article-comparison.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
}catch(e){$('status').textContent='Ошибка автономного просмотра: '+e;$('status').className='error'}
</script></html>'''
